def solve_arc_v3(grid):
    output = [row[:] for row in grid]

    # Iteratively fill 6s until none remain
    for iteration in range(20):
        changed = False

        for r in range(30):
            row = output[r]
            for c in range(30):
                if row[c] == 6:
                    # Strategy 1: Copy from vertical mirror (if not self-mirror)
                    mirror_r = 29 - r

                    if mirror_r != r and output[mirror_r][c] != 6:
                        row[c] = output[mirror_r][c]
                        changed = True
                    else:
                        # Strategy 2: Within-row horizontal mirror P2↔P3
                        if 8 <= c <= 15:  # P2
                            panel_idx = c - 8
                            mirror_c = 16 + (7 - panel_idx)  # Mirror in P3
                            if mirror_c < 30 and output[r][mirror_c] != 6:
                                row[c] = output[r][mirror_c]
                                changed = True
                            # Also check if vertical mirror exists and has P2, P3 mirror fill
                            elif mirror_r < 30:
                                if 8 <= mirror_c <= 15:
                                    m_panel_idx = mirror_c - 8
                                    m_mirror_c = 16 + (7 - m_panel_idx)
                                    if m_mirror_c < 30 and output[mirror_r][m_mirror_c] != 6:
                                        row[c] = output[mirror_r][m_mirror_c]
                                        changed = True
                        elif 16 <= c <= 23:  # P3
                            panel_idx = c - 16
                            mirror_c = 8 + (7 - panel_idx)  # Mirror in P2
                            if mirror_c < 30 and output[r][mirror_c] != 6:
                                row[c] = output[r][mirror_c]
                                changed = True
                            elif mirror_r < 30 and 8 <= mirror_c <= 15:
                                m_panel_idx = mirror_c - 8
                                m_mirror_c = 16 + (7 - m_panel_idx)
                                if m_mirror_c < 30 and output[mirror_r][m_mirror_c] != 6:
                                    row[c] = output[mirror_r][m_mirror_c]
                                    changed = True

        if not changed:
            break

    return output

